import { AbiCoder } from "ethers/lib/utils";
import { ethers } from "hardhat";

async function main() {
  // console.log("> ", ethers.utils.id("Withdraw(address[],uint256[])"));

  const dataOriginal = "";
  const AbiCoder = ethers.utils.defaultAbiCoder;
  const data = AbiCoder.decode(
    ["address[]",
      "uint256[]",
      "bytes"],
    dataOriginal
  );
  console.log("data: ", data);

  // console.log("=> ",AbiCoder.encode(["address","address","address"],['0xc29636912479eD45575DDCf4248dE8Aa6B80AF4C','0xa8dB691E433E291531A3a936Dd751dE380C6794c','0x10ED43C718714eb63d5aA57B78B54704E256024E']));
  // console.log("=> ",AbiCoder.encode(["address","address"],['0x8386D8eB039d9C8D103023AD3243761ec4c81C55','0x7F887ddD7EA01ba43a1b715F709d809307Fb4B22']));

}

// We recommend this pattern to be able to use async/await everywhere
// and properly handle errors.
main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
